        return None

    # Initialize the stack for DFS
    stack = [(start, [start])]
    visited = set()

    # Perform DFS
    while stack:
        (curr, path) = stack.pop()
        if curr in visited:
            continue
        visited.add(curr)

        # Check if goal is reached or can be reached
        if curr == goal:
            return path

        # Explore neighboring nodes
        for neighbor in graph[curr]:
            if neighbor not in visited:
                stack.append((neighbor, path + [neighbor]))

