def find_path(graph, start, goal):
    # A simple stack-based recursive path search
    def recursive_search(path, current_node, visited):
        if current_node == goal:
            return path + [current_node]
        visited.add(current_node)
        if current_node not in graph:
            return None
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                new_path = recursive_search(path + [current_node], neighbor, visited)
                if new_path:
                    return new_path
        return None

    return recursive_search([], start, set())
