def find_path(graph, start, goal):
    # Stack for the recursive search
    stack = [(pop, [pop]) for pop in (start, goal)]
    # Visited nodes to avoid cycles and redundant computations
    visited = set()

    # Recursive function to explore the graph
    def recurse(pop):
        visited.add(pop)
        if pop == goal:
            return True
        for node in graph.get(pop, []):
            if node not in visited and recurse(node):
                return True
        return False

    while stack:
        node, path = stack.pop()
        if node == goal:
            return path
        if recurse(node):
            return path
    return None
