def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Initialize the stack for the recursive path search
    def recursive_path_search(visited, stack, path, goal):
        if stack == [] or (visited and path[-1] == goal):
            return path if path[-1] == goal else None

        current = stack.pop()
        visited[current] = True
        for neighbor in graph[current]:
            if not visited[neighbor]:
                result = recursive_path_search(visited, stack, path + [neighbor], goal)
                if result is not None:
                    return result
        return None

    # Initialize the stack and visited set
    stack = [start]
    visited = {node: False for node in graph}
    visited[start] = True

    return recursive_path_search(visited, stack, [start], goal)

