def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Stack for the recursive and non-recursive stack
    stack = [(start, [start])]

    # Set for the recursive and non-recursive visited nodes
    visited = set()

    # Dictionary to hold the predecessor for each node in the path
    predecessor = {node: None for node in graph}

    while stack:
        (current, path) = stack.pop()

        if current not in visited:
            visited.add(current)

            if current == goal:
                return path

            for neighbor in graph[current]:
                if neighbor not in visited:
                    stack.append((neighbor, path + [neighbor]))
                    predecessor[neighbor] = current

    # If we have not returned from the while loop, goal is unreachable
